import os
from typing import Any, Dict, List, Optional

import requests


def _to_float(value: Any, default: float = 0.0) -> float:
    try:
        if value is None:
            return default
        return float(value)
    except (TypeError, ValueError):
        return default


def _extract_scores(resp_json: Dict[str, Any]) -> Dict[str, float]:
    scores: Dict[str, float] = {}

    # Perspective API response shape:
    # {
    #   "attributeScores": {
    #       "TOXICITY": {"summaryScore": {"value": 0.98, "type": "PROBABILITY"}},
    #       ...
    #   }
    # }
    attribute_scores = resp_json.get("attributeScores", {})
    if isinstance(attribute_scores, dict):
        for attr, payload in attribute_scores.items():
            if not isinstance(payload, dict):
                continue
            summary = payload.get("summaryScore", {})
            if isinstance(summary, dict):
                scores[str(attr)] = _to_float(summary.get("value"), 0.0)

    return scores


def _extract_thresholds_from_input(thresholds: Optional[Dict[str, Any]]) -> Dict[str, float]:
    normalized: Dict[str, float] = {}
    if not thresholds:
        return normalized
    for key, value in thresholds.items():
        normalized[str(key).upper()] = _to_float(value, 0.0)
    return normalized


def _default_attributes() -> List[str]:
    return [
        "TOXICITY",
        "SEVERE_TOXICITY",
        "IDENTITY_ATTACK",
        "INSULT",
        "PROFANITY",
        "THREAT",
        "SEXUALLY_EXPLICIT",
        "FLIRTATION",
    ]


def allow_text(text: str, thresholds: Optional[Dict[str, Any]] = None) -> Dict[str, Any]:
    """
    Evaluate text against Perspective API category thresholds.

    Returns a dict with:
      - allowed: bool
      - scores: dict of category scores
      - triggered: list of categories whose score met/exceeded threshold
      - error: optional error message
    """
    api_key = os.getenv("PERSPECTIVE_API_KEY")
    if not api_key:
        return {
            "allowed": False,
            "scores": {},
            "triggered": [],
            "error": "Missing PERSPECTIVE_API_KEY environment variable.",
        }

    thresholds_norm = _extract_thresholds_from_input(thresholds)
    requested_attributes = sorted(set(_default_attributes()) | set(thresholds_norm.keys()))

    url = "https://commentanalyzer.googleapis.com/v1alpha1/comments:analyze"
    payload: Dict[str, Any] = {
        "comment": {"text": text},
        "languages": ["en"],
        "requestedAttributes": {attr: {} for attr in requested_attributes},
        "doNotStore": True,
    }
    params = {"key": api_key}

    try:
        response = requests.post(url, params=params, json=payload, timeout=30)
        response.raise_for_status()
        data = response.json()
    except requests.RequestException as exc:
        return {
            "allowed": False,
            "scores": {},
            "triggered": [],
            "error": f"Perspective API request failed: {exc}",
        }
    except ValueError as exc:
        return {
            "allowed": False,
            "scores": {},
            "triggered": [],
            "error": f"Invalid JSON response from Perspective API: {exc}",
        }

    scores = _extract_scores(data)

    triggered: List[str] = []
    for category, threshold in thresholds_norm.items():
        score = scores.get(category, 0.0)
        if score >= threshold:
            triggered.append(category)

    allowed = len(triggered) == 0

    return {
        "allowed": allowed,
        "scores": scores,
        "triggered": triggered,
    }
